chrome.runtime.onInstalled.addListener(()=>{chrome.sidePanel.setPanelBehavior({openPanelOnActionClick:!1}),chrome.contextMenus.create({id:"add-all-tabs",title:"Add all tabs to Collections",contexts:["all"]})});chrome.contextMenus.onClicked.addListener((e,t)=>{e.menuItemId});chrome.runtime.onMessage.addListener((e,t,n)=>{e.type==="PIN_PANEL"&&(chrome.sidePanel.setPanelBehavior({openPanelOnActionClick:!0}),n({success:!0})),e.type==="UNPIN_PANEL"&&(chrome.sidePanel.setPanelBehavior({openPanelOnActionClick:!1}),n({success:!0}))});
